const EDGE_COLOR = [82, 43, 255];
const CENTER_COLOR = [143, 160, 255];

export function render(element, context) {
	const { React, ReactDOM, Recharts } = context.libs;
	const { PieChart, Pie, Cell, Tooltip, ResponsiveContainer } = Recharts;
	const h = React.createElement;

	const labelKey = context.config.xAxisKey;
	const valueKey = context.config.series[0]?.data_key;
	const rows = context.data
		.map((row) => ({ name: String(row[labelKey] ?? ''), value: Number(row[valueKey]) }))
		.filter((row) => Number.isFinite(row.value) && row.value > 0)
		.sort((left, right) => right.value - left.value);
	const total = rows.reduce((sum, row) => sum + row.value, 0) || 1;

	const isDark = context.theme === 'dark';
	const foreground = isDark ? '#f4f4f5' : '#18181b';
	const muted = isDark ? '#a1a1aa' : '#71717a';

	const sliceLabel = (props) => {
		if (props.percent < 0.04) return null;
		return h(
			'text',
			{
				x: props.x,
				y: props.y,
				fill: muted,
				fontSize: 11,
				textAnchor: props.x > props.cx ? 'start' : 'end',
				dominantBaseline: 'central',
			},
			`${Math.round(props.percent * 100)}%`,
		);
	};

	const legend = h(
		'div',
		{
			style: {
				display: 'flex',
				flexWrap: 'wrap',
				justifyContent: 'center',
				gap: '6px 16px',
				padding: '4px 8px 8px',
			},
		},
		rows.map((row, index) =>
			h(
				'span',
				{
					key: index,
					style: {
						display: 'inline-flex',
						alignItems: 'center',
						gap: '6px',
						fontSize: '12px',
						color: foreground,
					},
				},
				h('span', {
					style: {
						width: '10px',
						height: '10px',
						borderRadius: '3px',
						background: sliceColor(index, rows.length),
					},
				}),
				row.name,
				h(
					'span',
					{ style: { color: muted, fontVariantNumeric: 'tabular-nums' } },
					row.value.toLocaleString(),
				),
			),
		),
	);

	const chart = h(
		'div',
		{ style: { width: '100%', height: '100%', minHeight: '300px', display: 'flex', flexDirection: 'column' } },
		h(
			'div',
			{ style: { flex: 1, minHeight: '220px' } },
			h(
				ResponsiveContainer,
				{ width: '100%', height: '100%' },
				h(
					PieChart,
					{ margin: { top: 16, right: 24, bottom: 0, left: 24 } },
					h(
						Pie,
						{
							data: rows,
							dataKey: 'value',
							nameKey: 'name',
							cx: '50%',
							cy: '78%',
							startAngle: 180,
							endAngle: 0,
							innerRadius: '38%',
							outerRadius: '92%',
							paddingAngle: 4,
							cornerRadius: 3,
							stroke: 'none',
							isAnimationActive: true,
							label: sliceLabel,
							labelLine: false,
						},
						rows.map((row, index) =>
							h(Cell, { key: index, fill: sliceColor(index, rows.length) }),
						),
					),
					h(Tooltip, {
						formatter: (value, name) => [
							`${Number(value).toLocaleString()} (${Math.round((Number(value) / total) * 100)}%)`,
							name,
						],
						contentStyle: {
							background: isDark ? '#18181b' : '#ffffff',
							border: `1px solid ${isDark ? '#3f3f46' : '#e4e4e7'}`,
							borderRadius: '8px',
							color: foreground,
							fontSize: '12px',
						},
					}),
				),
			),
		),
		legend,
	);

	const root = ReactDOM.createRoot(element);
	root.render(chart);
	return () => {
		root.unmount();
		element.replaceChildren();
	};
}

/**
 * Echoes the nao logo gradient: deep purple on the outer rays,
 * lighter periwinkle toward the middle ray.
 */
function sliceColor(index, count) {
	if (count <= 1) return toRgb(EDGE_COLOR);
	const position = index / (count - 1);
	const t = 1 - Math.abs(2 * position - 1);
	return toRgb(EDGE_COLOR.map((channel, i) => Math.round(channel + (CENTER_COLOR[i] - channel) * t)));
}

function toRgb(channels) {
	return `rgb(${channels[0]}, ${channels[1]}, ${channels[2]})`;
}

