const ACCENT = '#522BFF';
const CORRECT = '#16a34a';
const WRONG = '#dc2626';
const ROUNDS = 8;
const OPTIONS_PER_ROUND = 4;

export function render(element, context) {
	const labelKey = context.config.xAxisKey;
	const palette = buildPalette(context.theme);
	const places = buildPlaces(context.data, labelKey);

	if (places.length < OPTIONS_PER_ROUND) {
		element.replaceChildren(
			makeElement('div', { color: palette.muted, fontSize: '13px', padding: '16px' },
				`The geo guesser needs at least ${OPTIONS_PER_ROUND} distinct places in the results.`),
		);
		return () => element.replaceChildren();
	}

	const game = {
		rounds: shuffle(places).slice(0, Math.min(ROUNDS, places.length)),
		index: 0,
		score: 0,
		timer: null,
	};

	startGame();

	return () => {
		clearTimeout(game.timer);
		element.replaceChildren();
	};

	function startGame() {
		game.index = 0;
		game.score = 0;
		game.rounds = shuffle(places).slice(0, Math.min(ROUNDS, places.length));
		renderRound();
	}

	function renderRound() {
		const place = game.rounds[game.index];
		const options = shuffle([
			place.name,
			...pickDistractors(places, place.name, OPTIONS_PER_ROUND - 1),
		]);

		const card = makeCard();
		card.append(
			makeHeader(`Round ${game.index + 1} / ${game.rounds.length}`, `Score ${game.score}`),
			makeElement('div', { color: palette.foreground, fontSize: '14px', fontWeight: '600' },
				'Which place matches these clues?'),
			makeClueBox(place),
			makeOptionsGrid(options, place.name),
		);
		element.replaceChildren(card);
	}

	function makeOptionsGrid(options, correctName) {
		const grid = makeElement('div', {
			display: 'grid',
			gridTemplateColumns: 'repeat(auto-fit, minmax(140px, 1fr))',
			gap: '8px',
		});
		const buttons = options.map((name) => makeOptionButton(name));
		for (const button of buttons) {
			button.addEventListener('click', () => resolveGuess(button, buttons, correctName));
		}
		grid.append(...buttons);
		return grid;
	}

	function resolveGuess(clicked, buttons, correctName) {
		const isCorrect = clicked.textContent === correctName;
		if (isCorrect) game.score += 1;

		for (const button of buttons) {
			button.disabled = true;
			button.style.cursor = 'default';
			if (button.textContent === correctName) {
				button.style.borderColor = CORRECT;
				button.style.color = CORRECT;
			} else if (button === clicked) {
				button.style.borderColor = WRONG;
				button.style.color = WRONG;
			} else {
				button.style.opacity = '0.5';
			}
		}

		game.timer = setTimeout(() => {
			game.index += 1;
			if (game.index < game.rounds.length) renderRound();
			else renderFinale();
		}, 1200);
	}

	function renderFinale() {
		const ratio = game.score / game.rounds.length;
		const verdict = ratio === 1 ? 'Perfect run.' : ratio >= 0.5 ? 'Nicely played.' : 'The map wins this time.';

		const card = makeCard();
		card.style.alignItems = 'center';
		card.style.textAlign = 'center';

		const replay = makeOptionButton('Play again');
		replay.style.borderColor = ACCENT;
		replay.style.color = ACCENT;
		replay.addEventListener('click', startGame);

		card.append(
			makeElement('div', { fontSize: '32px' }, ratio >= 0.5 ? '\u{1F30D}' : '\u{1F9ED}'),
			makeElement('div', { color: palette.foreground, fontSize: '18px', fontWeight: '700' },
				`${game.score} / ${game.rounds.length}`),
			makeElement('div', { color: palette.muted, fontSize: '13px' }, verdict),
			replay,
		);
		element.replaceChildren(card);
	}

	function makeCard() {
		return makeElement('div', {
			display: 'flex',
			flexDirection: 'column',
			gap: '14px',
			padding: '16px',
			borderRadius: '12px',
			border: `1px solid ${palette.border}`,
			background: palette.surface,
			fontFamily: 'inherit',
		});
	}

	function makeHeader(leftText, rightText) {
		const header = makeElement('div', {
			display: 'flex',
			justifyContent: 'space-between',
			fontSize: '12px',
			color: palette.muted,
			fontVariantNumeric: 'tabular-nums',
		});
		header.append(
			makeElement('span', {}, leftText),
			makeElement('span', { color: ACCENT, fontWeight: '600' }, rightText),
		);
		return header;
	}

	function makeClueBox(place) {
		const box = makeElement('div', {
			display: 'flex',
			flexDirection: 'column',
			gap: '6px',
			padding: '12px',
			borderRadius: '10px',
			background: palette.clueBackground,
		});
		for (const clue of place.clues) {
			const line = makeElement('div', { display: 'flex', gap: '8px', fontSize: '13px' });
			line.append(
				makeElement('span', { color: palette.muted, minWidth: '120px' }, clue.label),
				makeElement('span', { color: palette.foreground, fontWeight: '600', fontVariantNumeric: 'tabular-nums' }, clue.value),
			);
			box.append(line);
		}
		return box;
	}

	function makeOptionButton(text) {
		const button = document.createElement('button');
		button.type = 'button';
		button.textContent = text;
		Object.assign(button.style, {
			padding: '10px 12px',
			borderRadius: '10px',
			border: `1px solid ${palette.border}`,
			background: 'transparent',
			color: palette.foreground,
			fontSize: '13px',
			fontWeight: '500',
			cursor: 'pointer',
			transition: 'border-color 0.15s, opacity 0.15s',
		});
		return button;
	}
}

function buildPlaces(data, labelKey) {
	const seen = new Set();
	const places = [];
	for (const row of data) {
		const name = String(row[labelKey] ?? '').trim();
		if (!name || seen.has(name)) continue;
		seen.add(name);
		places.push({ name, clues: buildClues(row, labelKey) });
	}
	return places.filter((place) => place.clues.length > 0);
}

function buildClues(row, labelKey) {
	return Object.entries(row)
		.filter(([key, value]) => key !== labelKey && value !== null && value !== undefined)
		.slice(0, 5)
		.map(([key, value]) => ({
			label: prettifyKey(key),
			value: typeof value === 'number' ? value.toLocaleString() : String(value),
		}));
}

function prettifyKey(key) {
	const words = key.replace(/[_-]+/g, ' ').replace(/([a-z])([A-Z])/g, '$1 $2').toLowerCase();
	return words.charAt(0).toUpperCase() + words.slice(1);
}

function pickDistractors(places, correctName, count) {
	return shuffle(places.filter((place) => place.name !== correctName))
		.slice(0, count)
		.map((place) => place.name);
}

function shuffle(items) {
	const copy = [...items];
	for (let i = copy.length - 1; i > 0; i -= 1) {
		const j = Math.floor(Math.random() * (i + 1));
		[copy[i], copy[j]] = [copy[j], copy[i]];
	}
	return copy;
}

function buildPalette(theme) {
	const isDark = theme === 'dark';
	return {
		foreground: isDark ? '#f4f4f5' : '#18181b',
		muted: isDark ? '#a1a1aa' : '#71717a',
		border: isDark ? '#3f3f46' : '#e4e4e7',
		surface: isDark ? '#18181b' : '#ffffff',
		clueBackground: isDark ? '#27272a' : '#f4f4f5',
	};
}

